#include <Arduino.h>

#include "textutils.h"

namespace {
    struct TextReplacement {
        const char* from;
        const char* to;
    };

    // Generated by ChatGPT
    constexpr TextReplacement CHAR_MAP[] = {
        // German
        {"ß", "ss"},

        // French
        {"œ", "oe"},
        {"Œ", "OE"},
        {"À", "A"}, {"Â", "A"},
        {"È", "E"}, {"Ê", "E"}, {"Ë", "E"},
        {"Î", "I"}, {"Ï", "I"},
        {"Ô", "O"},
        {"Ù", "U"}, {"Û", "U"},

        // Italian / Romansh
        {"Ì", "I"}, {"Í", "I"},
        {"Ò", "O"}, {"Ó", "O"},
        {"Ú", "U"},

        // Typography
        {"’", "'"}, {"‘", "'"},
        {"“", "\""}, {"”", "\""},
        {"–", "-"}, {"—", "-"},
        {"…", "..."},
        {" ", " "}  // Non-breaking space (U+00A0)
    };
}


String sanitizeText(String text) {
    for (const auto& replacement : CHAR_MAP) {
        text.replace(replacement.from, replacement.to);
    }

    return text;
}


String removeLeadingZeros(String text) {
    int i=0;
    while (i < text.length() && text[i] == '0') {
        i++;
    }

    return text.substring(i);
}
